// Task A task: one piece of work Sinatra does, from any source.
type Task struct {
	// CreatedAt When the task was created.
	CreatedAt time.Time `json:"createdAt"`

	// Id The task's id. Use it as `taskId` in the task endpoints.
	Id string `json:"id"`

	// LastActivityAt When the task last did something. `null` if it hasn't yet.
	LastActivityAt *time.Time `json:"lastActivityAt"`

	// PullRequest The task's pull request. `null` until one opens.
	PullRequest *PullRequest `json:"pullRequest"`

	// Queued `true` while the task's agent waits because the workspace is already running as many agents at a time as its plan allows. The dashboard shows this as Waiting.
	Queued bool `json:"queued"`

	// Repo `owner/name` of the task's repository. `null` until a repository is chosen.
	Repo *string `json:"repo"`

	// Source Where the task started: `api` for the CLI, MCP, this API or the dashboard, `linear` or `github_issue` for an issue, `slack` or `telegram` for a chat. Other sources can appear, so treat an unknown value as a task started elsewhere.
	Source string `json:"source"`

	// Status Where the task is in its life, such as `pending`, `implementing`, `replied`, `pr_open` or `completed`. New statuses can appear, so don't treat the list as closed. See [Raw statuses](https://docs.sinatra.dev/docs/getting-started/how-it-works#raw-statuses) for each one.
	Status string `json:"status"`

	// Title The task's title: its issue's title, or a chat task's name. `null` for a task whose issue has no title, or a chat task not yet named.
	Title *string `json:"title"`

	// Url The task's page in the Sinatra dashboard, where anyone in the workspace can follow it. On a task started from the CLI, MCP, API or dashboard they can reply there too.
	Url *string `json:"url"`
}

// TaskList A page of tasks.
type TaskList struct {
	// NextCursor Pass it back as `cursor` to get the next page. Treat it as opaque. `null` on the last page.
	NextCursor *string `json:"nextCursor"`

	// Tasks The page's tasks, most recently active first.
	Tasks []Task `json:"tasks"`
}

// Ticket An open issue you could delegate to Sinatra.
type Ticket struct {
	// Context The Linear team's name, or the GitHub repository's name.
	Context *string `json:"context"`

	// Id The issue's id on Sinatra's side. For GitHub it looks like `github:owner/name#42`.
	Id string `json:"id"`

	// Identifier What to delegate it by. A Linear identifier such as `ENG-123` (send it as `id`), or a GitHub `owner/name#42` (send `owner/name` as `repo` and `42` as `number`).
	Identifier string `json:"identifier"`

	// Source Where the issue lives: `linear` or `github`. New sources can appear.
	Source string `json:"source"`

	// State A GitHub issue's state, such as `open`. `null` for a Linear issue.
	State *string `json:"state"`

	// Title The issue's title.
	Title string `json:"title"`

	// Url The issue's address on its tracker.
	Url string `json:"url"`

	// WorkspaceId The id of the workspace that was searched.
	WorkspaceId string `json:"workspaceId"`

	// WorkspaceLabel The name the dashboard's ticket picker gives that workspace.
	WorkspaceLabel string `json:"workspaceLabel"`

	// Yours `true` if the issue is assigned to you or you wrote it.
	Yours bool `json:"yours"`
}

// TicketSearchResult The issues you could delegate, and how the workspace is connected to each tracker.
type TicketSearchResult struct {
	// Github The workspace's GitHub connection.
	Github struct {
		// Connected Whether the workspace is connected to GitHub.
		Connected bool `json:"connected"`

		// Repo The repository the GitHub search covered, when the `repo` query matched an enabled one and had open issues. Otherwise `null`.
		Repo *string `json:"repo"`
	} `json:"github"`

	// Linear The workspace's Linear connection, as it applies to you.
	Linear struct {
		// Connected Whether the workspace is connected to Linear.
		Connected bool `json:"connected"`

		// IdentityBound Whether your Linear identity is tied to your Sinatra user.
		IdentityBound bool `json:"identityBound"`

		// IdentityLinked Whether your Linear account is linked in this workspace. Linear issues are listed only when it is.
		IdentityLinked bool `json:"identityLinked"`
	} `json:"linear"`

	// Tickets The issues you could delegate. Linear issues come first, then GitHub's, each with yours before your team's unassigned ones.
	Tickets []Ticket `json:"tickets"`
}

